import re
t = open("/opt/data/cache/scratch/ws/moodlesync/docs/ocr-avancement.md", encoding="utf8").read().split("\n")
start = next(i for i, l in enumerate(t) if l.startswith("## 6"))
rows = {}
for l in t[start:]:
    m = re.match(r"\| (\d+) \|", l)
    if m:
        rows[int(m.group(1))] = [c.strip() for c in l.strip().strip("|").split(" | ")]

def plage(s):
    out = []
    for p in s.split(","):
        p = p.strip()
        if " à " in p:
            a, b = p.split(" à ")
            out += list(range(int(a), int(b) + 1))
        else:
            out.append(int(p))
    return out

IMP = plage("12, 17, 43, 51, 52, 107, 116, 153, 154, 155, 175, 188, 212, 216, 232, 233, 234, 240, 247, 253, 276, 277, 278, 279, 280, 281")
MIN = plage("18, 19, 20, 21, 22, 34, 38, 39, 40, 46 à 49, 53 à 58, 63 à 66, 70, 72, 73, 75, 89, 90, 96, 99 à 105, 108 à 115, 117 à 121, 134, 136, 137, 139 à 146, 156 à 171, 176, 177, 181, 189, 193, 194, 196 à 211, 217 à 221, 223 à 225, 227 à 231, 235 à 237, 239, 241, 248 à 252, 254 à 260, 262, 263, 271 à 275, 282 à 286, 288, 289")
SANS = plage("2 à 5, 10, 11, 122 à 128, 147 à 152, 172 à 174, 182 à 186")
print(len(IMP), len(MIN), len(SANS), "total prompt", len(IMP) + len(MIN) + len(SANS))
manquent = [n for n in IMP + MIN + SANS if n not in rows]
print("absents:", manquent)

def classe(n):
    c = rows[n][-1]
    bas = c.lower()
    # derniere affirmation: on cherche le dernier mot-cle d'etat
    pos = {}
    for mot in ("fermé", "ferme ", "tranché", "accepté", "ouvert", "reporté", "partiellement"):
        i = bas.rfind(mot)
        if i >= 0:
            pos[mot] = i
    if not pos:
        return "?"
    return max(pos, key=pos.get)

import collections
for nom, liste in (("IMP", IMP), ("MIN", MIN), ("SANS", SANS)):
    d = collections.defaultdict(list)
    for n in liste:
        d[classe(n)].append(n)
    print(nom)
    for k, v in d.items():
        print("  ", k, len(v), v)

